package demo.pharma.payment;
import demo.pharma.audit.AuditService; import demo.pharma.common.exception.*; import demo.pharma.security.*; import lombok.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class PaymentService {
 private final PurchaseInvoiceRepository invoices; private final SupplierPaymentRepository payments; private final DemoPaymentTransactionRepository terminal; private final UserRepository users; private final AuditService audit;
 @Transactional public SupplierPayment pay(UUID invoiceId,BigDecimal amount,PaymentMethod method,String reference,String notes){if(amount==null||amount.signum()<=0)throw new BusinessException("Payment amount must be greater than zero");PurchaseInvoice invoice=invoices.findById(invoiceId).orElseThrow(()->new NotFoundException("Purchase invoice",invoiceId));BigDecimal paid=payments.totalPaid(invoiceId);BigDecimal outstanding=invoice.getTotal().subtract(paid);if(amount.compareTo(outstanding)>0)throw new BusinessException("Payment cannot exceed outstanding balance of "+outstanding);SupplierPayment p=new SupplierPayment();p.setSupplier(invoice.getSupplier());p.setPurchaseInvoice(invoice);p.setAmount(amount);p.setPaymentMethod(method);p.setReferenceNumber(reference);p.setPaymentDate(LocalDate.now());p.setNotes(notes);p.setCreatedBy(currentUser());payments.save(p);updateStatus(invoice,paid.add(amount));audit.logCurrent("SUPPLIER_PAYMENT_CREATED","SUPPLIER_PAYMENT",p.getId(),null,amount.toPlainString());return p;}
 @Transactional public DemoPaymentTransaction charge(String referenceType,UUID referenceId,BigDecimal amount,PaymentMethod method,String notes){if(referenceType==null||referenceType.isBlank())throw new BusinessException("Reference type is required");if(amount==null||amount.signum()<=0)throw new BusinessException("Amount must be greater than zero");DemoPaymentTransaction t=new DemoPaymentTransaction();t.setReferenceType(referenceType.trim().toUpperCase());t.setReferenceId(referenceId);t.setAmount(amount);t.setPaymentMethod(method);t.setTerminalReference("DEMO-"+UUID.randomUUID().toString().replace("-","").substring(0,16).toUpperCase());t.setNotes(notes);t.setCreatedBy(currentUser());terminal.save(t);audit.logCurrent("DEMO_PAYMENT_APPROVED","PAYMENT",t.getId(),null,t.getTerminalReference());return t;}
 @Transactional public PurchaseInvoice createInvoice(String number,LocalDate date,demo.pharma.supplier.Supplier supplier,demo.pharma.purchase.PurchaseOrder order,BigDecimal subtotal,BigDecimal discount,BigDecimal tax){if(invoices.existsByInvoiceNumberIgnoreCase(number))throw new BusinessException("Invoice number already exists");PurchaseInvoice i=new PurchaseInvoice();i.setInvoiceNumber(number);i.setInvoiceDate(date);i.setSupplier(supplier);i.setPurchaseOrder(order);i.setSubtotal(n(subtotal));i.setDiscount(n(discount));i.setTax(n(tax));i.setTotal(n(subtotal).subtract(n(discount)).add(n(tax)));invoices.save(i);audit.logCurrent("PURCHASE_INVOICE_CREATED","PURCHASE_INVOICE",i.getId(),null,number);return i;}
 public BigDecimal outstanding(PurchaseInvoice invoice){return invoice.getTotal().subtract(payments.totalPaid(invoice.getId()));} private void updateStatus(PurchaseInvoice i,BigDecimal paid){i.setPaymentStatus(paid.signum()==0?PaymentStatus.UNPAID:paid.compareTo(i.getTotal())>=0?PaymentStatus.PAID:PaymentStatus.PARTIALLY_PAID);invoices.save(i);} private BigDecimal n(BigDecimal v){return v==null?BigDecimal.ZERO:v;} private AppUser currentUser(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null)return null;String name=a.getName();return users.findByUsernameIgnoreCaseOrEmailIgnoreCase(name,name).orElse(null);}}
